import{_ as a,o as r,c as t,a5 as i}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"Manual permanent deletion","description":"","frontmatter":{},"headers":[],"relativePath":"feature/manual-trash-purge/spec.md","filePath":"feature/manual-trash-purge/spec.md"}'),n={name:"feature/manual-trash-purge/spec.md"};function s(l,e,o,d,c,u){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="manual-permanent-deletion" tabindex="-1">Manual permanent deletion <a class="header-anchor" href="#manual-permanent-deletion" aria-label="Permalink to &quot;Manual permanent deletion&quot;">​</a></h1><p>Users may request permanent deletion of one trashed file or all accessible trash files in the current workspace without waiting 30 days. Active files and client vault files are excluded. Existing ownership/audience checks remain authoritative. Active references block deletion. Confirmation uses BrandHub modal, names the single file, and explicitly states that bulk affects all accessible trash regardless of filters/pages. Requests are irreversible once queued; storage cleanup, history removal, audit and quota release reuse the purge worker. No actual customer deletion is performed during development.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li>POST individual purge returns updated material; POST trash/purge returns requested/skipped counts.</li><li>Version conflict and permission checks apply; blocked/dependency failures never delete storage or release quota.</li><li>Existing 30-day automatic retention remains unchanged.</li><li>VI/EN keys under library.trash are parallel: purge, emptyTrash, purgeTitle, emptyTrashTitle, purgeDescription, emptyTrashDescription, purgeQueued, purgeUnavailable, referenced, bulkPurgeQueued.</li><li>Light/dark: use existing semantic tokens and shared Dialog/Button components. Keyboard focus begins on Cancel; pending prevents duplicate requests and dismissal.</li></ul><h2 id="readiness-correction" tabindex="-1">Readiness correction <a class="header-anchor" href="#readiness-correction" aria-label="Permalink to &quot;Readiness correction&quot;">​</a></h2><p>Explicit user deletion is independent of automatic 30-day purge feature flags. When automatic flags are false, the worker may claim only explicit requests bearing both request timestamp and actor. Permission, references, provider identity, verified quota inventory, lease, storage confirmation and audit checks remain mandatory. Unverified accounting must fail before deleting any storage object. Automatic expiry remains gated.</p><h2 id="trash-visibility-and-folders" tabindex="-1">Trash visibility and folders <a class="header-anchor" href="#trash-visibility-and-folders" aria-label="Permalink to &quot;Trash visibility and folders&quot;">​</a></h2><p>Accepted permanent deletions are excluded from trash rows AND counts while storage cleanup runs. Folder permanent deletion requires a trashed root and all contained folders/files to be authorized and in trash; referenced files block the entire folder request. Queue file requests and remove folder tree atomically under the existing tree lock. No active folder or client vault is included. Folder deletion uses BrandHub confirmation modal with recursive warning and VI/EN keys folderPurgeTitle, folderPurgeDescription, folderPurgeBlocked, folderPurged.</p>',8)])])}const h=a(n,[["render",s]]);export{m as __pageData,h as default};
